    const float32x4_t yl0_h0_z0_vh = vaddq_f32(yl0_h0_z0_sh, yl0_h0_z0_c);
    const float32x4_t yl0_h0_z0_vh_z = vsubq_f32(yl0_h0_z0_vh, yl0_h0_z0_sh);
