        // (step_z0, step_z1) = mul_pow2_2(x0, x1, c)
        const double step_z0_h = fma_rn(x0, c, 0.0);
        const double step_z0_l = fma_rn(x1, c, 0.0);
        // (step_z0, step_z1) = fast_two_sum(step_z0_h, step_z0_l)
